window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7079db790b9b056c"]={"versions": [{"id": "FIG-7079db790b9b056c", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Schutzfunktion <code>E2E_P04Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4). Das Diagramm spezifiziert die Gesamtabfolge der Schutzschritte bei der Absicherung eines zu übertragenden Datenbereichs auf Senderseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätsaufruf / Funktion</strong>: <code>E2E_P04Protect(Config, State, Data, Length)</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Konfigurationsstruktur des Profils 4\n</li><li><code>State</code>: Zustandsstruktur des Schutzes\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array\n</li><li><code>Length</code>: Länge der Daten in Bytes\n</li></ul>\n</li><li><strong>Aktionen / Sub-Aktivitäten</strong> (jeweils mit Unterdiagramm-Symbol gekennzeichnet):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Write DataID</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li><strong>Knoten</strong>: Ein Startknoten (Initial Node) und drei Endknoten (Activity Final Nodes) für Rückgabewerte:\n<ul class=\"fig-list\"><li><code>INPUTERR_NULL</code> (vollständig: <code>E2E_E_INPUTERR_NULL</code>)\n</li><li><code>return E2E_E_OK</code>\n</li><li><code>return E2E_...</code> (vollständig: <code>return E2E_E_INPUTERR_WRONG</code>)\n</li></ul>\n</li><li><strong>Guards</strong>: <code>[input ok]</code>, <code>[wrong input]</code>, impliziter Null-Fehler-Pfad.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt am Startknoten beim Aufruf von <code>E2E_P04Protect(Config, State, Data, Length)</code>.\n</li><li>Erste Aktion ist <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand der Eingangsprüfung:\n<ul class=\"fig-list\"><li>Bei fehlerhafter Null-Referenz führt die linke Kante direkt zum Endknoten für <code>INPUTERR_NULL</code>.\n</li><li>Bei ungültigen Eingabewerten (<code>[wrong input]</code>) führt die rechte Kante direkt zum Endknoten für Eingabefehler (<code>return E2E_...</code>).\n</li><li>Bei erfolgreicher Validierung (<code>[input ok]</code>) wird der Hauptpfad sequenziell abgearbeitet:\n a. <code>Compute offset</code>\n b. <code>Write Length</code>\n c. <code>Write Counter</code>\n d. <code>Write DataID</code>\n e. <code>Compute CRC</code>\n f. <code>Write CRC</code>\n g. <code>Increment Counter</code>\n</li></ul>\n</li><li>Nach dem Inkrementieren des Zählers terminiert die Funktion erfolgreich am mittleren Endknoten mit <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ gemäß [PRS_E2E_00362] für das Verhalten der Funktion <code>E2E_P04Protect</code>. Alle Teilaktivitäten sind als aufrufende Aktionen mit referenzierten Sub-Aktivitätsdiagrammen spezifiziert (z. B. <code>Verify inputs of the protect function</code> gemäß [PRS_E2E_00363]). Bei fehlerhaften Parametern bricht der Schutz unverzüglich ohne Modifikation der Nutzdaten oder Zählerinkrementierung ab. Die Absicherungsschritte erfordern deterministische Reihenfolge: Zuerst Platzierung bzw. Berechnung von Offset, Länge, Counter und DataID, danach Berechnung und Eintrag der CRC-Prüfsumme, gefolgt von der Erhöhung des Counters im Zustandsvektor.</p>"}, {"id": "FIG-d7e621bde3752da2", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Schutzfunktion <code>E2E_P04Protect</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4). Das Diagramm spezifiziert die Gesamtabfolge der Schutzschritte bei der Absicherung eines zu übertragenden Datenbereichs auf Senderseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätsaufruf / Funktion</strong>: <code>E2E_P04Protect(Config, State, Data, Length)</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Konfigurationsstruktur des Profils 4\n</li><li><code>State</code>: Zustandsstruktur des Schutzes\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array\n</li><li><code>Length</code>: Länge der Daten in Bytes\n</li></ul>\n</li><li><strong>Aktionen / Sub-Aktivitäten</strong> (jeweils mit Unterdiagramm-Symbol gekennzeichnet):\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Write DataID</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n</li><li><strong>Knoten</strong>: Ein Startknoten (Initial Node) und drei Endknoten (Activity Final Nodes) am unteren Rand (Beschriftungen am Bildrand beschnitten).\n</li><li><strong>Guards</strong>: <code>[input ok]</code>, <code>[wrong input]</code>, <code>[null input]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt am Startknoten beim Aufruf von <code>E2E_P04Protect(Config, State, Data, Length)</code>.\n</li><li>Erste Aktion ist <code>Verify inputs of the protect function</code>.\n</li><li>Verzweigung anhand der Eingangsprüfung:\n<ul class=\"fig-list\"><li>Bei fehlerhafter Null-Referenz führt die linke Kante direkt zum Endknoten für <code>INPUTERR_NULL</code>.\n</li><li>Bei ungültigen Eingabewerten (<code>[wrong input]</code>) führt die rechte Kante direkt zum Endknoten für Eingabefehler (<code>return E2E_...</code>).\n</li><li>Bei erfolgreicher Validierung (<code>[input ok]</code>) wird der Hauptpfad sequenziell abgearbeitet:\n a. <code>Compute offset</code>\n b. <code>Write Length</code>\n c. <code>Write Counter</code>\n d. <code>Write DataID</code>\n e. <code>Compute CRC</code>\n f. <code>Write CRC</code>\n g. <code>Increment Counter</code>\n</li></ul>\n</li><li>Nach dem Inkrementieren des Zählers terminiert die Funktion erfolgreich am mittleren Endknoten mit <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ gemäß [PRS_E2E_00362] für das Verhalten der Funktion <code>E2E_P04Protect</code>. Alle Teilaktivitäten sind als aufrufende Aktionen mit referenzierten Sub-Aktivitätsdiagrammen spezifiziert (z. B. <code>Verify inputs of the protect function</code> gemäß [PRS_E2E_00363]). Bei fehlerhaften Parametern bricht der Schutz unverzüglich ohne Modifikation der Nutzdaten oder Zählerinkrementierung ab. Die Absicherungsschritte erfordern deterministische Reihenfolge: Zuerst Platzierung bzw. Berechnung von Offset, Länge, Counter und DataID, danach Berechnung und Eintrag der CRC-Prüfsumme, gefolgt von der Erhöhung des Counters im Zustandsvektor.</p>"}], "trans": [{"from": "FIG-7079db790b9b056c", "to": "FIG-d7e621bde3752da2", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Verzweigungs-Guard am linken Pfad von <code>Verify inputs of the protect function</code>: Guard-Beschriftung <code>[null input]</code> ist nun direkt an der Kante unterhalb der Verzweigung platziert.\n</li><li>Guard-Beschriftung <code>[wrong input]</code> am rechten Pfad: Zeilenumbruch zu zweizeiliger Darstellung (<code>[wrong</code> / <code>input]</code>).\n</li><li>Guard-Beschriftung <code>[input ok]</code> am zentralen Pfad: Zeilenumbruch zu zweizeiliger Darstellung (<code>[input</code> / <code>ok]</code>).\n</li><li>Funktionsaufruf am Startknoten: Signatur <code>E2E_P04Protect(Config, State, Data, Length)</code> zweizeilig umgebrochen (<code>E2E_P04Protect(Config, State, Data,</code> / <code>Length)</code>).\n</li><li>Endknoten-Beschriftungen am unteren Bildrand: Beschriftungen <code>INPUTERR_NULL</code>, <code>return E2E_E_OK</code> und <code>return E2E_...</code> sind durch verändertes Rendering/Clipping am unteren Rand teilweise abgeschnitten (nur noch Fragmente bzw. <code>return</code> sichtbar).\n</li></ul>"}]};
